initial.code:
const view = { ...{"screen": "opendt-overview", "window": "week", "markers": "on", "period": "day"}, period: '${period}', markers: '${markers}' };
context.panel.patchFormValue(view);
context.panel.setInitial({ ...context.panel.initial, ...view });

update.code:
const response = context.panel.response;
if (response && response.ok) {
  const sent = Object.fromEntries(context.panel.elements.map((e) => [e.id, e.value]));
  context.panel.setInitial({ ...context.panel.initial, ...sent });
  context.grafana.notifySuccess(['OpenDT', 'Sent to the twin']);
} else if (response) {
  response.json().then(({ detail }) => context.grafana.notifyError(['OpenDT', typeof detail === 'string' ? detail : detail.map((d) => d.msg).join('; ')]));
}

options.elementValueChanged:
const { id, value } = context.element;
const view = ["screen", "window", "period", "markers"];
if (view.includes(id)) {
  context.panel.initial[id] = value;  // a view setting: applied at once, not sent to the twin
  const url = context.grafana.locationService;
  const range = url.getSearchObject();
  if (id === 'screen') url.push(`/d/${value}?from=${range.from || '2022-10-06T22:00:00.000Z'}&to=${range.to || '2022-10-13T22:00:00.000Z'}`);
  if (id === 'period') url.partial({ 'var-period': value });
  if (id === 'markers') url.partial({ 'var-markers': value });
  if (id === 'window') {
    const end = new Date(context.panel.initial.twin_time).getTime();
    const hours = { day: 24, hours: 6 }[value];
    url.partial(hours ? { from: end - hours * 3600000, to: end } : {"from": "2022-10-06T22:00:00.000Z", "to": "2022-10-13T22:00:00.000Z"});
  }
}

resetAction.code:
if (document.fullscreenElement) {
  document.exitFullscreen();
  context.grafana.locationService.partial({ kiosk: null });
} else {
  document.documentElement.requestFullscreen();
  context.grafana.locationService.partial({ kiosk: true });
}

